<?php
namespace App\Command;
use App\Service\Store;
use App\Security\User;
use Symfony\Component\Console\Attribute\AsCommand;
use Symfony\Component\Console\Command\Command;
use Symfony\Component\Console\Input\InputInterface;
use Symfony\Component\Console\Output\OutputInterface;
use Symfony\Component\Console\Style\SymfonyStyle;
use Symfony\Component\PasswordHasher\Hasher\UserPasswordHasherInterface;
#[AsCommand(name:'app:installer',description:'Créer le schéma, les types de repas et le premier administrateur.')]
final class InstallCommand extends Command {
    public function __construct(private readonly Store $store, private readonly UserPasswordHasherInterface $hasher) { parent::__construct(); }
    protected function execute(InputInterface $input,OutputInterface $output): int {
        $io=new SymfonyStyle($input,$output);
        if (!$input->isInteractive()) { $io->error('Installation interactive requise pour créer le premier administrateur.');return Command::FAILURE; }
        $mysql=$this->store->db->getDatabasePlatform() instanceof \Doctrine\DBAL\Platforms\AbstractMySQLPlatform;
        $postgres=$this->store->db->getDatabasePlatform() instanceof \Doctrine\DBAL\Platforms\PostgreSQLPlatform;
        $id=$postgres?'INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY':($mysql?'INTEGER PRIMARY KEY AUTO_INCREMENT':'INTEGER PRIMARY KEY AUTOINCREMENT');
        $tail=$mysql?' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci':'';
        $tables=[
            'direction'=>"id $id, nom VARCHAR(100) NOT NULL UNIQUE",
            'service'=>"id $id, nom VARCHAR(100) NOT NULL, direction_id INTEGER NOT NULL, UNIQUE(nom,direction_id), FOREIGN KEY(direction_id) REFERENCES direction(id)",
            'employe'=>"id $id, matricule VARCHAR(50) NOT NULL UNIQUE, nom VARCHAR(100) NOT NULL, prenoms VARCHAR(150) NOT NULL, service_id INTEGER NOT NULL, actif INTEGER NOT NULL DEFAULT 1, badge_token VARCHAR(64) NOT NULL UNIQUE, FOREIGN KEY(service_id) REFERENCES service(id)",
            'utilisateur'=>"id $id, email VARCHAR(180) NOT NULL UNIQUE, nom VARCHAR(150) NOT NULL, mot_de_passe VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, actif INTEGER NOT NULL DEFAULT 1, employe_id INTEGER NULL UNIQUE, FOREIGN KEY(employe_id) REFERENCES employe(id)",
            'type_repas'=>"id $id, nom VARCHAR(100) NOT NULL UNIQUE, actif INTEGER NOT NULL DEFAULT 1",
            'menu'=>"id $id, date_repas VARCHAR(10) NOT NULL, type_repas_id INTEGER NOT NULL, contenu TEXT NOT NULL, prix DECIMAL(12,2) NOT NULL DEFAULT 0, observations TEXT NOT NULL, UNIQUE(date_repas,type_repas_id), FOREIGN KEY(type_repas_id) REFERENCES type_repas(id)",
            'ticket'=>"id $id, numero VARCHAR(50) NOT NULL UNIQUE, token VARCHAR(64) NOT NULL UNIQUE, employe_id INTEGER NOT NULL, date_repas VARCHAR(10) NOT NULL, type_repas_id INTEGER NOT NULL, statut VARCHAR(20) NOT NULL, cree_le VARCHAR(19) NOT NULL, cree_par INTEGER NOT NULL, UNIQUE(employe_id,date_repas,type_repas_id), FOREIGN KEY(employe_id) REFERENCES employe(id), FOREIGN KEY(type_repas_id) REFERENCES type_repas(id), FOREIGN KEY(cree_par) REFERENCES utilisateur(id)",
            'consommation'=>"id $id, ticket_id INTEGER NOT NULL UNIQUE, employe_id INTEGER NOT NULL, type_repas_id INTEGER NOT NULL, date_repas VARCHAR(10) NOT NULL, servi_le VARCHAR(19) NOT NULL, agent_id INTEGER NOT NULL, matricule VARCHAR(50) NOT NULL, employe_nom VARCHAR(251) NOT NULL, service_nom VARCHAR(100) NOT NULL, direction_nom VARCHAR(100) NOT NULL, repas_nom VARCHAR(100) NOT NULL, FOREIGN KEY(ticket_id) REFERENCES ticket(id), FOREIGN KEY(employe_id) REFERENCES employe(id), FOREIGN KEY(type_repas_id) REFERENCES type_repas(id), FOREIGN KEY(agent_id) REFERENCES utilisateur(id)",
            'audit'=>"id $id, utilisateur_id INTEGER NULL, action VARCHAR(60) NOT NULL, detail TEXT NOT NULL, cree_le VARCHAR(19) NOT NULL, FOREIGN KEY(utilisateur_id) REFERENCES utilisateur(id)"
        ];
        foreach ($tables as $name=>$cols) { $this->store->db->executeStatement("CREATE TABLE IF NOT EXISTS $name ($cols)$tail"); }
        foreach (['Petit déjeuner','Déjeuner','Dîner','Collation'] as $nom) {
            if (!$this->store->db->fetchOne('SELECT id FROM type_repas WHERE nom=?',[$nom])) { $this->store->db->insert('type_repas',['nom'=>$nom,'actif'=>1]); }
        }
        // Index complémentaires, installation relançable sans supprimer les données.
        foreach (['idx_ticket_date'=>'ticket(date_repas,statut)','idx_consommation_date'=>'consommation(date_repas)','idx_audit_date'=>'audit(cree_le)'] as $index=>$table) {
            $tableName=substr($table,0,strpos($table,'('));
            $indexes=$this->store->db->createSchemaManager()->listTableIndexes($tableName);
            if (!isset($indexes[$index])) { $this->store->db->executeStatement("CREATE INDEX $index ON $table"); }
        }
        if ($this->store->db->fetchOne("SELECT id FROM utilisateur WHERE role='ROLE_ADMIN' AND actif=1")) { $io->success('Schéma disponible ; administrateur déjà présent.');return Command::SUCCESS; }
        $email=$io->ask('Adresse e-mail de l’administrateur',null,fn($v)=>filter_var($v,FILTER_VALIDATE_EMAIL)?strtolower($v):throw new \RuntimeException('Adresse e-mail invalide.'));
        $nom=$io->ask('Nom affiché','Administrateur');
        $password=$io->askHidden('Mot de passe (12 caractères minimum)',fn($v)=>strlen((string)$v)>=12?$v:throw new \RuntimeException('12 caractères minimum.'));
        $confirmation=$io->askHidden('Confirmez le mot de passe');
        if ($confirmation!==$password) { $io->error('Les mots de passe diffèrent. Relancez l’installation.');return Command::FAILURE; }
        if ($this->store->db->fetchOne('SELECT id FROM utilisateur WHERE email=?',[$email])) { $io->error('Cette adresse existe déjà. Utilisez une autre adresse.');return Command::FAILURE; }
        $u=new User(0,$email,'','ROLE_ADMIN',true,null,$nom);
        $this->store->db->insert('utilisateur',['email'=>$email,'nom'=>$nom,'mot_de_passe'=>$this->hasher->hashPassword($u,$password),'role'=>'ROLE_ADMIN','actif'=>1,'employe_id'=>null]);
        $adminId=(int)$this->store->db->fetchOne('SELECT id FROM utilisateur WHERE email=?',[$email]);
        $this->store->audit($adminId,'INSTALLATION','Premier administrateur');
        $io->success('Application installée. Aucun mot de passe par défaut.');return Command::SUCCESS;
    }
}
